insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_art3_v1'
from (values
('117.304.c.1.A',3,'A student studies how three photographers frame the same street scene and adapts the best qualities for her own series. This is an example of what?','["Analyzing sources for visual characteristics and flexibility in ideas", "Copying exactly", "Picking a color at random", "Ignoring sources"]'::jsonb,0,'Analysis of sources supports flexible, original thinking.','original'),
('117.304.c.1.A',3,'Why do advanced art students analyze multiple visual sources before beginning a series?','["To shorten the project", "To find varied ideas and avoid relying on one approach", "To reduce originality", "To avoid making choices"]'::jsonb,1,'Several sources widen the options.','original'),
('117.304.c.1.B',3,'Which comparison best contrasts two elements of art in a painting?','["The title is long", "The artist is famous", "The jagged lines create tension while the smooth curves feel calm", "The frame is large"]'::jsonb,2,'Contrasting elements shows their different effects.','original'),
('117.304.c.1.B',3,'A student compares how warm and cool hues affect the mood of two paintings. She is comparing which element?','["Line", "Form", "Texture", "Color"]'::jsonb,3,'Warm and cool hues affect mood.','original'),
('117.304.c.1.C',3,'Two posters both use repetition. In the first the shapes repeat evenly, and in the second they change size across the page. The second adds what principle?','["Rhythm and movement", "Only balance", "Perfect symmetry", "Only unity"]'::jsonb,0,'Varying repeated shapes creates rhythm.','original'),
('117.304.c.1.C',3,'Comparing contrast and unity in a design, a student finds that contrast does what?','["Makes all parts identical", "Creates visual interest by placing different elements together", "Prevents balance", "Removes emphasis"]'::jsonb,1,'Contrast highlights differences.','original'),
('117.304.c.1.D',3,'A student decides between oil paint and acrylic for a quick-drying study. She is exploring what?','["The teacher''s preference only", "The cost of frames only", "The suitability of art media and processes", "The size of the studio"]'::jsonb,2,'Choosing media means judging suitability.','original'),
('117.304.c.1.D',3,'An artist selects clay for a piece meant to feel organic and handmade. This shows what?','["Rejecting craft", "Choosing at random", "Avoiding planning", "Selecting a medium that expresses her idea"]'::jsonb,3,'The medium fits the concept.','original'),
('117.304.c.2.A',3,'A student explores a theme of memory with a drawing, a collage and a small sculpture before choosing the final form. This shows what?','["Developing multiple solutions from original sources", "Using one idea", "Avoiding exploration", "Skipping the planning stage"]'::jsonb,0,'Several attempts lead to a stronger solution.','original'),
('117.304.c.2.A',3,'Which step is part of creating multiple solutions for a visual problem?','["Painting the final piece immediately", "Making several thumbnail sketches before committing", "Waiting for inspiration only", "Copying a classmate"]'::jsonb,1,'Thumbnails explore options.','original'),
('117.304.c.2.B',3,'A designer must create a logo that works in color and in black and white. She tests several versions to solve this problem. What does this show?','["Choosing the first idea", "Making random edits", "Solving visual problems with multiple solutions", "Ignoring constraints"]'::jsonb,2,'Testing alternatives solves design problems.','original'),
('117.304.c.2.B',3,'A product package must be eye-catching and also easy to read. Which design choice best addresses both needs?','["No text at all", "A busy pattern behind tiny text", "Only decorative lettering", "A bold image paired with a clear, readable label"]'::jsonb,3,'Both attraction and clarity are needed.','original'),
('117.304.c.2.C',3,'A student uses a photograph she took herself as source material. Compared with using a stranger''s photo, she has what advantage?','["She owns the copyright and does not need permission", "She cannot alter it", "She must pay a fee", "It is automatically public domain"]'::jsonb,0,'Creators own their own original images.','original'),
('117.304.c.2.C',3,'If a source work is under copyright, an artist can ethically appropriate its imagery by doing what?','["Selling it unchanged", "Transforming it substantially, giving credit and following legal limits", "Hiding the source", "Copying it exactly"]'::jsonb,1,'Responsible appropriation transforms and credits.','original'),
('117.304.c.2.D',3,'A student layers fragments of old letters in a mixed-media piece to express the passage of time. This is an example of what?','["Tracing a template", "Reproducing a poster", "Communicating ideas through original artwork", "Following a recipe"]'::jsonb,2,'Original work expresses ideas.','original'),
('117.304.c.2.D',3,'Which feature most strongly makes an artwork communicate an impression of calm?','["Crowded dark shapes", "Sharp diagonals", "Jagged red lines", "Soft colors, open space and gentle horizontal lines"]'::jsonb,3,'Quiet elements suggest calm.','original'),
('117.304.c.2.E',3,'Three students plan a large installation in which each builds a part. Which practice makes the collaboration succeed?','["Agreeing on a shared concept and schedule", "Ignoring deadlines", "Changing a teammate''s work without asking", "Working in secret"]'::jsonb,0,'Shared planning supports collaboration.','original'),
('117.304.c.2.E',3,'What is a benefit of collaborating on an artwork?','["It lowers creativity", "It brings together different skills and perspectives", "It removes all ideas", "It shortens learning"]'::jsonb,1,'Teams combine strengths.','original'),
('117.304.c.2.F',3,'An artist wants to show fine detail in a portrait. Which tool is most appropriate?','["A wide sponge", "A thick marker only", "A fine-point pen or sharp pencil", "A large house brush"]'::jsonb,2,'Fine detail needs fine tools.','original'),
('117.304.c.2.F',3,'A student selects intaglio printing to create delicate lines with deep contrast. This choice shows what?','["Random selection", "Avoiding planning", "Following no rules", "Matching medium and process to the intended expression"]'::jsonb,3,'Process choice supports intent.','original'),
('117.304.c.3.A',3,'A student researches Cubism and notes how artists showed several viewpoints at once. She is researching what?','["A historical style and its characteristics", "A weather pattern", "A sports rule", "A grammar rule"]'::jsonb,0,'Cubism is a historical style.','original'),
('117.304.c.3.A',3,'Which source is best for researching a historical art period?','["A gossip post", "A museum catalog or scholarly art history book", "A random ad", "An anonymous comment"]'::jsonb,1,'Credible sources provide accurate history.','original'),
('117.304.c.3.B',3,'A student sees that Japanese woodblock prints influenced European painters in the 1800s. She is distinguishing what?','["The paper''s weight", "Prices of prints", "The influence of one culture on another''s art", "The size of paper"]'::jsonb,2,'Art ideas travel between cultures.','original'),
('117.304.c.3.B',3,'Which characteristic of an artwork might link it to a particular culture?','["The frame brand", "The room temperature", "The artist''s shoe size", "Symbols, materials and techniques tied to cultural traditions"]'::jsonb,3,'Cultural markers appear in symbols and materials.','original'),
('117.304.c.3.C',3,'A group designs a public sculpture for a park and surveys neighbors first. This is a good practice for what?','["Community-based art projects", "Private commissions only", "Hiding the work", "Ignoring audiences"]'::jsonb,0,'Community projects consider the public.','original'),
('117.304.c.3.C',3,'Why might an artist hold a community workshop while creating a public mural?','["To avoid permission", "To involve residents and reflect local stories", "To make it smaller", "To keep it secret"]'::jsonb,1,'Participation builds ownership.','original'),
('117.304.c.3.D',3,'A student writes a plan that lists steps to become a professional illustrator, including building a portfolio and finding clients. She is doing what?','["Choosing a hobby", "Avoiding research", "Developing a plan of action for a career in art", "Dropping art"]'::jsonb,2,'A plan lists concrete steps.','original'),
('117.304.c.3.D',3,'Which step would be part of a plan to start a small art business?','["Never sharing work", "Waiting without a plan", "Ignoring costs", "Pricing work, setting up a website and finding customers"]'::jsonb,3,'Entrepreneurship requires planning.','original'),
('117.304.c.4.A',3,'At a museum, a student explains why a painter chose a dim palette for a war scene. She is doing what?','["Interpreting and justifying artistic decisions in a professional artwork", "Ignoring the choice", "Avoiding the work", "Guessing the price"]'::jsonb,0,'Interpretation links choices to meaning.','original'),
('117.304.c.4.A',3,'Which evidence best supports an interpretation of a painting''s meaning?','["The age of the viewer", "Visible details such as symbols, composition and color", "The size of the museum", "The weather outside"]'::jsonb,1,'Evidence comes from the work.','original'),
('117.304.c.4.B',3,'After describing and analyzing an artwork in a critique, what is the next step?','["Selling it", "Hiding it", "Interpreting what it means and then evaluating its success", "Ignoring it"]'::jsonb,2,'Critique moves from describing to judging.','original'),
('117.304.c.4.B',3,'A well-formed critique should include what?','["Only personal taste", "Random guesses", "Vague praise", "Observations supported by evidence from the artwork"]'::jsonb,3,'Strong critiques cite evidence.','original'),
('117.304.c.4.C',3,'An artist writes a short statement explaining that her work explores family history through photographs and fabric. What is this?','["An artist''s statement", "A frame label only", "A signature", "A price tag"]'::jsonb,0,'Artist statements explain intent.','original'),
('117.304.c.4.C',3,'Why would an artist write about her own work?','["To replace the work", "To clarify her intent and help viewers understand it", "To lower the value", "To avoid being understood"]'::jsonb,1,'Writing clarifies meaning.','original'),
('117.304.c.4.D',3,'A peer says the focal point in her painting is unclear, so she adds contrast to the center. She is doing what?','["Copying the peer", "Dropping the piece", "Using a critique response to decide the next direction", "Ignoring feedback"]'::jsonb,2,'Critique guides decisions.','original'),
('117.304.c.4.D',3,'Which approach shows maturity in responding to critique?','["Rejecting all comments", "Arguing with every critic", "Changing everything immediately", "Listening openly and choosing which suggestions to apply"]'::jsonb,3,'Mature response weighs feedback.','original'),
('117.304.c.4.E',3,'A portfolio includes work arranged to show a progression of ideas from first sketches to finished pieces. This demonstrates what?','["Evaluating and analyzing personal work to show growth", "Random ordering", "Hiding process", "Avoiding reflection"]'::jsonb,0,'Organization shows development.','original'),
('117.304.c.4.E',3,'Which is a key reason to choose only your strongest pieces for a portfolio?','["It fills more pages", "It presents your best skills and a clear identity as an artist", "It hides growth", "It avoids reflection"]'::jsonb,1,'Selection shows quality and focus.','original'),
('117.304.c.4.F',3,'A student reviews a retrospective exhibition and explains how the artist''s methods grew more experimental over time. She is demonstrating what?','["Ignoring changes", "Counting artworks", "Analysis that recognizes innovation and personal style", "Reading labels only"]'::jsonb,2,'Analysis traces innovation across work.','original'),
('117.304.c.4.F',3,'What makes an artist''s work innovative?','["Exact copying of a master", "Tracing a photo", "Using the same method every time", "Fresh ideas or techniques that move beyond existing approaches"]'::jsonb,3,'Innovation is new thinking.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
